\title{Multivariate time series prediction using clustered echo state network}
\author{S. Hariharan, R. Suresh{$^*$}, V. K. Chandrasekar}

\institute{$^{1}$Department of Physics, Centre for Nonlinear Science and Engineering, School of Electrical and Electronics Engineering,\\ SASTRA Deemed University, Thanjavur 613 401, India. \\\\$^*$Corresponding author email: suresh@eee.sastra.edu}
